sys_script.script:
(function validateAiAnalysisInsert() {
    gs.debug('[Retail Store Assistant] Validate AI Analysis: processing new insert — analysis_number=' + current.getValue('analysis_number'));

    // Validate investigation reference
    var investigation = current.getValue('investigation');
    if (!investigation) {
        gs.error('[Retail Store Assistant] Validate AI Analysis: rejected — investigation reference is required');
        gs.addErrorMessage('AI Analysis rejected: an Investigation reference is required.');
        current.setAbortAction(true);
        return;
    }

    // Validate investigation exists
    var investGr = new GlideRecord('x_1945330_retail_0_investigation');
    if (!investGr.get(investigation)) {
        gs.error('[Retail Store Assistant] Validate AI Analysis: rejected — investigation ' + investigation + ' does not exist');
        gs.addErrorMessage('AI Analysis rejected: the referenced Investigation does not exist.');
        current.setAbortAction(true);
        return;
    }
    gs.debug('[Retail Store Assistant] Validate AI Analysis: investigation reference validated — ' + investigation);

    // Set default status
    if (!current.getValue('status')) {
        current.setValue('status', 'requested');
    }

    // Set requested_on if not already set
    if (!current.getValue('requested_on')) {
        var now = new GlideDateTime();
        current.setValue('requested_on', now.getDisplayValue());
        gs.debug('[Retail Store Assistant] Validate AI Analysis: auto-set requested_on');
    }

    gs.info('[Retail Store Assistant] Validate AI Analysis: validation passed — analysis_number=' + current.getValue('analysis_number') + ' investigation=' + investigation + ' type=' + current.getValue('analysis_type') + ' requested_by=' + current.getValue('requested_by'));
})();
